<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientRegisteredAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientRegisteredAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withRegisteredAt,
 * getRegisteredAt/registeredAt accessors, and isRegisteredAtChanged with/without original.
 */
class TrustedClientRegisteredAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withRegisteredAt creates a new instance with the RegisteredAt set
     * from a string value, and getRegisteredAt returns the primitive string.
     */
    public function testWithRegisteredAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegisteredAtAccessorUnitTest();

        // Act
        $result = $holder->withRegisteredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getRegisteredAt());
    }
    /**
     * Asserts that withregisteredAt has access to the value object
     * from a string value, and getRegisteredAt returns the primitive string.
     */
    public function testWithRegisteredAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegisteredAtAccessorUnitTest();

        // Act
        $result = $holder->withRegisteredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->registeredAt()->value());
    }
    public function testChangedRegisteredAt(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientRegisteredAtAccessorUnitTest();
        $original = $holder->withRegisteredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withRegisteredAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withRegisteredAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isRegisteredAtChanged();
        $withSame = $original->isRegisteredAtChanged($same);
        $withDiferent = $original->isRegisteredAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientRegisteredAtAccessorUnitTest
{
    use TrustedClientRegisteredAtAccessor;
}
